{"id":"1116b357-f2a9-43fe-9558-8a35ab4766cd","inserted_at":"2026-04-30T06:10:56.285552+00:00","updated_at":"2026-04-30T06:10:56.285552+00:00","type":"sql","name":"Attivazione RLS e policy di accesso per utenti e admin","description":"","content":{"sql":"-- 1. ATTIVAZIONE RLS SU TUTTE LE TABELLE CORE\r\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.pois ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.impact_transactions ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.active_sessions ENABLE ROW LEVEL SECURITY;\r\n\r\n-- PULIZIA EVENTUALI POLICY ESISTENTI (Per evitare conflitti)\r\nDROP POLICY IF EXISTS \"Gli utenti possono visualizzare solo il proprio profilo\" ON public.profiles;\r\nDROP POLICY IF EXISTS \"Gli utenti possono aggiornare solo il proprio profilo\" ON public.profiles;\r\nDROP POLICY IF EXISTS \"Tutti possono visualizzare i POI\" ON public.pois;\r\nDROP POLICY IF EXISTS \"Gli utenti vedono solo le proprie transazioni\" ON public.impact_transactions;\r\nDROP POLICY IF EXISTS \"Gli utenti gestiscono solo le proprie sessioni attive\" ON public.active_sessions;\r\nDROP POLICY IF EXISTS \"Tutti possono vedere le sessioni\" ON public.active_sessions;\r\nDROP POLICY IF EXISTS \"Gli utenti possono inserire sessioni\" ON public.active_sessions;\r\nDROP POLICY IF EXISTS \"Gli utenti possono aggiornare le proprie sessioni\" ON public.active_sessions;\r\n\r\n-- 2. POLICY PER \"PROFILES\"\r\nCREATE POLICY \"Gli utenti possono visualizzare solo il proprio profilo\" \r\nON public.profiles FOR SELECT \r\nUSING (auth.uid() = id);\r\n\r\nCREATE POLICY \"Gli utenti possono aggiornare solo il proprio profilo\" \r\nON public.profiles FOR UPDATE \r\nUSING (auth.uid() = id);\r\n\r\n-- 3. POLICY PER \"POIS\" \r\nCREATE POLICY \"Tutti possono visualizzare i POI\" \r\nON public.pois FOR SELECT \r\nTO authenticated, anon\r\nUSING (true);\r\n\r\n-- 4. POLICY PER \"IMPACT_TRANSACTIONS\" (CORRETTO: profile_id invece di user_id)\r\nCREATE POLICY \"Gli utenti vedono solo le proprie transazioni\" \r\nON public.impact_transactions FOR SELECT \r\nUSING (auth.uid() = profile_id);\r\n\r\n-- 5. POLICY PER \"ACTIVE_SESSIONS\"\r\nCREATE POLICY \"Gli utenti gestiscono solo le proprie sessioni attive\" \r\nON public.active_sessions FOR ALL \r\nUSING (auth.uid() = user_id);\r\n","content_id":"1116b357-f2a9-43fe-9558-8a35ab4766cd","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
